class _ReviewFormState extends State<ReviewForm> {
  final _text = TextEditingController();

  @override
  void dispose() {
    // Assumes Flutter always gets to tear the screen down
    drafts.save(_text.text);
    _text.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextField(controller: _text);
}

class _ReviewFormState extends State<ReviewForm> with RestorationMixin {
  // Restored by the OS after process death
  final _text = RestorableTextEditingController();

  @override
  String get restorationId => 'review_form';

  @override
  void restoreState(RestorationBucket? oldBucket, bool initialRestore) =>
      registerForRestoration(_text, 'text');

  @override
  void dispose() {
    _text.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextField(
        controller: _text.value,
        onChanged: drafts.saveSoon, // persist while in front
      );
}
